import{_ as a,o,c as i,a3 as d}from"./chunks/framework.enEKIwRN.js";const u=JSON.parse('{"title":"Command-Line Help for cicada","description":"","frontmatter":{},"headers":[],"relativePath":"reference/cli.md","filePath":"reference/cli.md"}'),t={name:"reference/cli.md"};function c(r,e,l,n,s,h){return o(),i("div",null,[...e[0]||(e[0]=[d('<h1 id="command-line-help-for-cicada" tabindex="-1">Command-Line Help for <code>cicada</code> <a class="header-anchor" href="#command-line-help-for-cicada" aria-label="Permalink to &quot;Command-Line Help for `cicada`&quot;">​</a></h1><p>This document contains the help content for the <code>cicada</code> command-line program.</p><p>calendars as code — declare calendars in YAML, reconcile like infrastructure</p><p><strong>Command Overview:</strong></p><ul><li><a href="#cicada"><code>cicada</code>↴</a></li><li><a href="#cicada-init"><code>cicada init</code>↴</a></li><li><a href="#cicada-validate"><code>cicada validate</code>↴</a></li><li><a href="#cicada-list"><code>cicada list</code>↴</a></li><li><a href="#cicada-plan"><code>cicada plan</code>↴</a></li><li><a href="#cicada-apply"><code>cicada apply</code>↴</a></li><li><a href="#cicada-refresh"><code>cicada refresh</code>↴</a></li><li><a href="#cicada-drift"><code>cicada drift</code>↴</a></li><li><a href="#cicada-range"><code>cicada range</code>↴</a></li><li><a href="#cicada-show"><code>cicada show</code>↴</a></li><li><a href="#cicada-fmt"><code>cicada fmt</code>↴</a></li><li><a href="#cicada-provider"><code>cicada provider</code>↴</a></li><li><a href="#cicada-provider-add"><code>cicada provider add</code>↴</a></li></ul><h2 id="cicada" tabindex="-1"><code>cicada</code> <a class="header-anchor" href="#cicada" aria-label="Permalink to &quot;`cicada`&quot;">​</a></h2><p>calendars as code — declare calendars in YAML, reconcile like infrastructure</p><p><strong>Usage:</strong> <code>cicada [COMMAND]</code></p><h6 id="commands" tabindex="-1"><strong>Commands:</strong> <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;**Commands:**&quot;">​</a></h6><ul><li><code>init</code> — Scaffold a cicada.yaml manifest and a starter calendar</li><li><code>validate</code> — Validate calendar YAML: schema shape plus domain invariants</li><li><code>list</code> — List the declared calendars: bindings plus declared/recorded event counts</li><li><code>plan</code> — Diff desired vs recorded vs live into an ordered plan — and issue the <code>planDigest</code> <code>apply --plan-digest</code> requires</li><li><code>apply</code> — Reconcile: execute the plan against the provider</li><li><code>refresh</code> — Pull live state into recorded state</li><li><code>drift</code> — Show recorded-vs-live drift</li><li><code>range</code> — Expand events over a time range (local; --provider for live)</li><li><code>show</code> — Show one event by stable local id</li><li><code>fmt</code> — Normalize calendar YAML formatting in place</li><li><code>provider</code> — Manage provider registrations (<code>provider add google</code>)</li></ul><h6 id="options" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>-h, --help</code> — Print help</li><li><code>-V, --version</code> — Print version</li></ul><h2 id="cicada-init" tabindex="-1"><code>cicada init</code> <a class="header-anchor" href="#cicada-init" aria-label="Permalink to &quot;`cicada init`&quot;">​</a></h2><p>Scaffold a cicada.yaml manifest and a starter calendar</p><p><strong>Usage:</strong> <code>cicada init [OPTIONS] [DIR]</code></p><h6 id="arguments" tabindex="-1"><strong>Arguments:</strong> <a class="header-anchor" href="#arguments" aria-label="Permalink to &quot;**Arguments:**&quot;">​</a></h6><ul><li><code>[DIR]</code> — Directory to scaffold into (default: current directory)</li></ul><h6 id="options-1" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-1" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--force</code> — Overwrite existing <code>cicada.yaml</code> / <code>calendars/work.yaml</code></li><li><code>-h, --help</code> — Print help</li></ul><h2 id="cicada-validate" tabindex="-1"><code>cicada validate</code> <a class="header-anchor" href="#cicada-validate" aria-label="Permalink to &quot;`cicada validate`&quot;">​</a></h2><p>Validate calendar YAML: schema shape plus domain invariants. With no files, discovers the <code>cicada.yaml</code> manifest in the current directory and validates every calendar it lists. A <code>kind: Manifest</code> file passed explicitly expands the same way.</p><p><strong>Usage:</strong> <code>cicada validate [FILES]...</code></p><h6 id="arguments-1" tabindex="-1"><strong>Arguments:</strong> <a class="header-anchor" href="#arguments-1" aria-label="Permalink to &quot;**Arguments:**&quot;">​</a></h6><ul><li><code>[FILES]...</code> — Calendar or manifest YAML files. Defaults to the <code>cicada.yaml</code> manifest in the current directory</li></ul><h6 id="options-2" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-2" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>-h, --help</code> — Print help (see a summary with &#39;-h&#39;)</li></ul><h2 id="cicada-list" tabindex="-1"><code>cicada list</code> <a class="header-anchor" href="#cicada-list" aria-label="Permalink to &quot;`cicada list`&quot;">​</a></h2><p>List the declared calendars: bindings plus declared/recorded event counts</p><p><strong>Usage:</strong> <code>cicada list [OPTIONS] [FILES]...</code></p><h6 id="arguments-2" tabindex="-1"><strong>Arguments:</strong> <a class="header-anchor" href="#arguments-2" aria-label="Permalink to &quot;**Arguments:**&quot;">​</a></h6><ul><li><code>[FILES]...</code> — Calendar or manifest YAML files. Defaults to the <code>cicada.yaml</code> manifest in the current directory</li></ul><h6 id="options-3" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-3" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--provider &lt;PROVIDER&gt;</code> — Provider name used for calendars without <code>provider:</code> (fake | google; default fake)</li><li><code>--state &lt;STATE&gt;</code> — Recorded-state file (default <code>.cicada/state.yaml</code>; also <code>CICADA_STATE</code>)</li><li><code>-h, --help</code> — Print help</li></ul><h2 id="cicada-plan" tabindex="-1"><code>cicada plan</code> <a class="header-anchor" href="#cicada-plan" aria-label="Permalink to &quot;`cicada plan`&quot;">​</a></h2><p>Diff desired vs recorded vs live into an ordered plan — and issue the <code>planDigest</code> <code>apply --plan-digest</code> requires</p><p><strong>Usage:</strong> <code>cicada plan [OPTIONS] [FILES]...</code></p><h6 id="arguments-3" tabindex="-1"><strong>Arguments:</strong> <a class="header-anchor" href="#arguments-3" aria-label="Permalink to &quot;**Arguments:**&quot;">​</a></h6><ul><li><code>[FILES]...</code> — Calendar or manifest YAML files. Defaults to the <code>cicada.yaml</code> manifest in the current directory</li></ul><h6 id="options-4" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-4" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--provider &lt;PROVIDER&gt;</code> — Provider adapter to plan against (fake | google)</li><li><code>--fake-file &lt;FAKE_FILE&gt;</code> — Fake provider backend file (test/demo only; default <code>.cicada/fake-provider.json</code> beside the manifest)</li><li><code>--state &lt;STATE&gt;</code> — Recorded-state file (default <code>.cicada/state.yaml</code> beside the manifest; <code>CICADA_STATE</code> also overrides)</li><li><code>--out &lt;OUT&gt;</code> — Write the plan JSON here (<code>cicada/plan-v1</code>); a JSON array when more than one calendar is planned</li><li><code>--notify &lt;NOTIFY&gt;</code> — Attendee notifications: none | externalOnly | all — must match the choice <code>apply</code> uses or the plan digest goes stale</li><li><code>-h, --help</code> — Print help</li></ul><h2 id="cicada-apply" tabindex="-1"><code>cicada apply</code> <a class="header-anchor" href="#cicada-apply" aria-label="Permalink to &quot;`cicada apply`&quot;">​</a></h2><p>Reconcile: execute the plan against the provider. <code>--plan-digest &lt;sha256:…&gt;</code> applies only the exact plan a <code>cicada plan</code> run previewed — the digest is consumed on use and counts as the confirmation (no prompt).</p><p><strong>Usage:</strong> <code>cicada apply [OPTIONS] [FILES]...</code></p><h6 id="arguments-4" tabindex="-1"><strong>Arguments:</strong> <a class="header-anchor" href="#arguments-4" aria-label="Permalink to &quot;**Arguments:**&quot;">​</a></h6><ul><li><code>[FILES]...</code> — Calendar or manifest YAML files. Defaults to the <code>cicada.yaml</code> manifest in the current directory</li></ul><h6 id="options-5" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-5" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--provider &lt;PROVIDER&gt;</code> — Provider adapter to apply against (fake | google)</li><li><code>--fake-file &lt;FAKE_FILE&gt;</code> — Fake provider backend file (test/demo only; default <code>.cicada/fake-provider.json</code> beside the manifest)</li><li><code>--state &lt;STATE&gt;</code> — Recorded-state file (default <code>.cicada/state.yaml</code>; also <code>CICADA_STATE</code>)</li><li><code>--auto-approve</code> — Skip the confirmation prompt</li><li><code>--resume</code> — Resume after a crash — skip already-journaled ops</li><li><code>--force</code> — Overwrite out-of-band edits instead of failing on drift conflict (ADR-0002 §4)</li><li><code>--notify &lt;NOTIFY&gt;</code> — Attendee notifications: none | externalOnly | all</li><li><code>--plan-digest &lt;DIGEST&gt;</code> — Apply only the plan this digest previewed (printed by <code>cicada plan</code> as <code>planDigest sha256:…</code>). The digest must have been issued and not spent, and the re-planned digest must match — anything changed since preview refuses as stale. Providing it is the confirmation: the prompt is skipped</li><li><code>-h, --help</code> — Print help (see a summary with &#39;-h&#39;)</li></ul><h2 id="cicada-refresh" tabindex="-1"><code>cicada refresh</code> <a class="header-anchor" href="#cicada-refresh" aria-label="Permalink to &quot;`cicada refresh`&quot;">​</a></h2><p>Pull live state into recorded state</p><p><strong>Usage:</strong> <code>cicada refresh [OPTIONS]</code></p><h6 id="options-6" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-6" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--provider &lt;PROVIDER&gt;</code> — Provider adapter to refresh from (fake | google)</li><li><code>--fake-file &lt;FAKE_FILE&gt;</code> — Fake provider backend file (test/demo only)</li><li><code>--state &lt;STATE&gt;</code> — Recorded-state file (default <code>.cicada/state.yaml</code>; also <code>CICADA_STATE</code>)</li><li><code>-h, --help</code> — Print help</li></ul><h2 id="cicada-drift" tabindex="-1"><code>cicada drift</code> <a class="header-anchor" href="#cicada-drift" aria-label="Permalink to &quot;`cicada drift`&quot;">​</a></h2><p>Show recorded-vs-live drift</p><p><strong>Usage:</strong> <code>cicada drift [OPTIONS]</code></p><h6 id="options-7" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-7" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--provider &lt;PROVIDER&gt;</code> — Provider adapter to check against (fake | google)</li><li><code>--fake-file &lt;FAKE_FILE&gt;</code> — Fake provider backend file (test/demo only)</li><li><code>--state &lt;STATE&gt;</code> — Recorded-state file (default <code>.cicada/state.yaml</code>; also <code>CICADA_STATE</code>)</li><li><code>-h, --help</code> — Print help</li></ul><h2 id="cicada-range" tabindex="-1"><code>cicada range</code> <a class="header-anchor" href="#cicada-range" aria-label="Permalink to &quot;`cicada range`&quot;">​</a></h2><p>Expand events over a time range (local; --provider for live)</p><p><strong>Usage:</strong> <code>cicada range [OPTIONS] [FILES]...</code></p><h6 id="arguments-5" tabindex="-1"><strong>Arguments:</strong> <a class="header-anchor" href="#arguments-5" aria-label="Permalink to &quot;**Arguments:**&quot;">​</a></h6><ul><li><code>[FILES]...</code> — Calendar or manifest YAML files. Defaults to the <code>cicada.yaml</code> manifest in the current directory</li></ul><h6 id="options-8" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-8" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--calendar &lt;CALENDAR&gt;</code> — Limit to one declared calendar name; default all</li><li><code>--from &lt;FROM&gt;</code> — Range start (<code>today</code>, <code>+Nd</code>, a date, or a datetime)</li><li><code>--to &lt;TO&gt;</code> — Range end (<code>+7d</code>, a date, or a datetime)</li><li><code>--provider &lt;PROVIDER&gt;</code> — Expand the live provider&#39;s events instead of local YAML (fake | google)</li><li><code>-h, --help</code> — Print help</li></ul><h2 id="cicada-show" tabindex="-1"><code>cicada show</code> <a class="header-anchor" href="#cicada-show" aria-label="Permalink to &quot;`cicada show`&quot;">​</a></h2><p>Show one event by stable local id</p><p><strong>Usage:</strong> <code>cicada show [OPTIONS] &lt;ID&gt; [FILES]...</code></p><h6 id="arguments-6" tabindex="-1"><strong>Arguments:</strong> <a class="header-anchor" href="#arguments-6" aria-label="Permalink to &quot;**Arguments:**&quot;">​</a></h6><ul><li><code>&lt;ID&gt;</code> — Stable local id of the event</li><li><code>[FILES]...</code> — Calendar or manifest YAML files. Defaults to the <code>cicada.yaml</code> manifest in the current directory</li></ul><h6 id="options-9" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-9" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--from &lt;FROM&gt;</code> — Occurrence window start (<code>today</code>, <code>+Nd</code>, a date, or a datetime). With <code>--to</code>, defaults to <code>today</code></li><li><code>--to &lt;TO&gt;</code> — Occurrence window end (defaults to the window start + 30d)</li><li><code>--provider &lt;PROVIDER&gt;</code> — Show the live provider&#39;s version of the event (found via its <code>cicada:id</code> tag) instead of the declared YAML</li><li><code>-h, --help</code> — Print help</li></ul><h2 id="cicada-fmt" tabindex="-1"><code>cicada fmt</code> <a class="header-anchor" href="#cicada-fmt" aria-label="Permalink to &quot;`cicada fmt`&quot;">​</a></h2><p>Normalize calendar YAML formatting in place</p><p><strong>Usage:</strong> <code>cicada fmt [OPTIONS] [FILES]...</code></p><h6 id="arguments-7" tabindex="-1"><strong>Arguments:</strong> <a class="header-anchor" href="#arguments-7" aria-label="Permalink to &quot;**Arguments:**&quot;">​</a></h6><ul><li><code>[FILES]...</code> — Files to format; defaults to the manifest&#39;s calendars</li></ul><h6 id="options-10" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-10" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--check</code> — Check only — exit nonzero when a file isn&#39;t canonical; writes nothing (CI-friendly)</li><li><code>--sort</code> — Sort events by stable id instead of preserving file order</li><li><code>-h, --help</code> — Print help</li></ul><h2 id="cicada-provider" tabindex="-1"><code>cicada provider</code> <a class="header-anchor" href="#cicada-provider" aria-label="Permalink to &quot;`cicada provider`&quot;">​</a></h2><p>Manage provider registrations (<code>provider add google</code>)</p><p><strong>Usage:</strong> <code>cicada provider &lt;COMMAND&gt;</code></p><h6 id="commands-1" tabindex="-1"><strong>Commands:</strong> <a class="header-anchor" href="#commands-1" aria-label="Permalink to &quot;**Commands:**&quot;">​</a></h6><ul><li><code>add</code> — Register a provider (OAuth flow / service account)</li></ul><h6 id="options-11" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-11" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>-h, --help</code> — Print help</li></ul><h2 id="cicada-provider-add" tabindex="-1"><code>cicada provider add</code> <a class="header-anchor" href="#cicada-provider-add" aria-label="Permalink to &quot;`cicada provider add`&quot;">​</a></h2><p>Register a provider (OAuth flow / service account)</p><p><strong>Usage:</strong> <code>cicada provider add [OPTIONS] &lt;NAME&gt;</code></p><h6 id="arguments-8" tabindex="-1"><strong>Arguments:</strong> <a class="header-anchor" href="#arguments-8" aria-label="Permalink to &quot;**Arguments:**&quot;">​</a></h6><ul><li><code>&lt;NAME&gt;</code> — Provider name (<code>google</code>)</li></ul><h6 id="options-12" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-12" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--service-account &lt;KEY_JSON&gt;</code> — Register a service-account key JSON instead of running the OAuth flow (non-interactive)</li><li><code>--client-id &lt;CLIENT_ID&gt;</code> — OAuth installed-app client id (else <code>CICADA_GOOGLE_CLIENT_ID</code>)</li><li><code>--client-secret &lt;CLIENT_SECRET&gt;</code> — OAuth installed-app client secret (else <code>CICADA_GOOGLE_CLIENT_SECRET</code>)</li><li><code>--code &lt;CODE&gt;</code> — Authorization code — skips the interactive prompt</li><li><code>-h, --help</code> — Print help</li></ul>',92)])])}const g=a(t,[["render",c]]);export{u as __pageData,g as default};
